```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name = 'geo.Geo/Nearby' GROUP BY ALL ORDER BY attr_span_kind",
          "claim": "search's client span to geo.Geo/Nearby has p50 about 1467 ms, while geo's server span is about 0.14 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.trace_id, c.duration/1e6 client_ms, s.duration/1e6 server_ms, (s.time - c.time) server_start_offset FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.attr_span_kind='Server' AND s.service_name='geo' WHERE c.service_name='search' AND c.span_name='geo.Geo/Nearby' ORDER BY c.time LIMIT 30",
          "claim": "In matched traces, geo receives the request 1.3–2.7 s after search starts the call, then answers in about 0.1 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='search' AND span_name IN ('rate.Rate/GetRates','geo.Geo/Nearby') GROUP BY ALL",
          "claim": "search's calls to rate stay near normal (p95 about 8 ms), while only its calls to geo are slow (p95 about 2.75 s)."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name IN ('search','geo') AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "search's own server span p95 is about 2.76 s with zero errors; the delay is on the outgoing geo call, not in search's work."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, avg(value) avgv FROM abnormal_metrics WHERE service_name IN ('search','geo') AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set','k8s.pod.network.errors') GROUP BY ALL ORDER BY metric, service_name",
          "claim": "search and geo CPU, memory and network-error metrics stay near normal levels during the incident, so the slowdown is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name IN ('search.Search/Nearby','HTTP /hotels') GROUP BY ALL",
          "claim": "frontend's /hotels p50 is about 1.5 s, matching search.Search/Nearby at about 1.47 s; search is the source of the user-visible slowness."
        }
      ]
    }
  ]
}
```

